const ubigeo = String(query.ubigeo || '').trim();
if (!/^\d{6}$/.test(ubigeo)) {
  return JSON.stringify({ error: 'Debes ejecutar primero extraer_fuentes y predecir_riesgo para obtener un ubigeo numérico real de 6 dígitos antes de redactar_informe.' });
