const ubigeo = String(query.ubigeo || '').trim();
if (!/^\d{6}$/.test(ubigeo)) {
  return JSON.stringify({ error: 'Debes ejecutar primero extraer_fuentes, predecir_riesgo y redactar_informe para obtener un ubigeo numérico real de 6 dígitos antes de notificar.' });
}
const dci = Number.parseFloat(String(query.dci_proyectada_pct ?? '0'));
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://api_engine:8000/tools/notificar',
  body: {
    report_payload: {
      ubigeo,
      provincia: String(query.provincia || ''),
      distrito: String(query.distrito || ''),
      dci_proyectada_pct: Number.isFinite(dci) ? dci : 0,
      canal_destino: String(query.canal_destino || 'S5_ALGEDONICO'),
      sintesis_narrativa_s4: String(query.sintesis_narrativa_s4 || ''),
    },
  },
  json: true,
});
return JSON.stringify(res);

const raw = $input.first().json || {};
let parsed = {};
if (typeof raw.output === 'string') {
  const m = raw.output.match(/\{[\s\S]*\}/);
  if (m) {
    try { parsed = JSON.parse(m[0]); } catch (e) { parsed = {}; }
  }
} else if (typeof raw.dci_proyectada_pct === 'number') {
  parsed = { ...raw };
}

const needsFallback = !parsed.ubigeo || !parsed.distrito || typeof parsed.dci_proyectada_pct !== 'number' || !parsed.id_alerta;
if (needsFallback) {
  const predRes = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://api_engine:8000/predict',
    body: { anio_corte: 2024 },
    json: true,
  });
  const rows = (predRes.distritos_criticos_s5 && predRes.distritos_criticos_s5.length) ? predRes.distritos_criticos_s5 : (predRes.predicciones_distritales || []);
  rows.sort((a, b) => Number(b.dci_proyectada_pct || 0) - Number(a.dci_proyectada_pct || 0));
  const top = rows[0] || { ubigeo: '090411', distrito: 'Santa Ana', provincia: 'Castrovirreyna', dci_proyectada_pct: 29.29 };
  let explainCtx = top;
  try {
    explainCtx = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://api_engine:8000/tools/explicar_riesgo/${top.ubigeo}`,
      json: true,
    });
  } catch (e) {
    explainCtx = { ubigeo: top.ubigeo, distrito: top.distrito, provincia: top.provincia, red_salud: top.red_salud, dci_actual_pct: top.dci_actual_pct, dci_proyectada_pct: top.dci_proyectada_pct };
  }
  const infRes = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://api_engine:8000/tools/redactar_informe',
    body: { district_context: explainCtx, prefer_provider: 'gemini' },
    json: true,
  });
  const inf = infRes.informe || {};
  const notRes = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://api_engine:8000/tools/notificar',
    body: { report_payload: inf },
    json: true,
  });
  parsed = {
    ubigeo: inf.ubigeo || top.ubigeo,
    distrito: inf.distrito || top.distrito,
    provincia: inf.provincia || top.provincia,
    dci_proyectada_pct: Number(inf.dci_proyectada_pct ?? top.dci_proyectada_pct ?? 25.0),
    id_alerta: Number(notRes.id_alerta || 1),
    canal_destino: inf.canal_destino || 'S5_ALGEDONICO',
    sintesis_narrativa_s4: inf.sintesis_narrativa_s4 || (typeof raw.output === 'string' ? raw.output.slice(0, 400) : 'Síntesis S4 generada.'),
  };
}
return [{ json: parsed }];
